package com.aetherteam.aether.data;

import net.fabricmc.fabric.api.datagen.v1.DataGeneratorEntrypoint;
import net.fabricmc.fabric.api.datagen.v1.FabricDataGenerator;

/**
 * The Fabric edition doesn't generate its own data: the contents of {@code src/generated/resources} are generated by the NeoForge edition
 * and copied here, as upstream does for the Fabric edition. The NeoForge data generators are kept below, commented out, for reference.
 */
public class AetherData implements DataGeneratorEntrypoint {
    @Override
    public void onInitializeDataGenerator(FabricDataGenerator fabricDataGenerator) {
    }
}

